import type { Artist } from '../lib/types';

export const ARTISTS: Artist[] = [
  { id: 'pierre-henry', name: 'Pierre Henry', origin: 'Paris, France', formed: 1949, active: '1949–2017', members: 'Solo composer', description: 'Co-founder of musique concrète with Pierre Schaeffer who then spent six decades treating the studio as an instrument. Henry\u2019s best work edits recorded sound the way a film editor cuts picture: abrupt, theatrical, and rhythmically exact.', factual: 'French composer (1927–2017); co-founded the Groupe de Recherches Musicales; known for Variations pour une porte et un soupir (1963).', genreIds: ['musique-concrete', 'tape-music'], labelIds: ['philips', 'ina-grm'] },
  { id: 'bernard-parmegiani', name: 'Bernard Parmegiani', origin: 'Paris, France', formed: 1960, active: '1960–2013', members: 'Solo composer', description: 'GRM composer whose pieces move like organisms: grains of sound gather into gestures, gestures into long arcs. De Natura Sonorum remains the clearest demonstration that studio composition can have phrasing as deliberate as any string quartet.', factual: 'French electroacoustic composer (1927–2013); member of GRM 1960–1992; composed De Natura Sonorum (1975).', genreIds: ['musique-concrete'], labelIds: ['ina-grm'] },
  { id: 'beatriz-ferreyra', name: 'Beatriz Ferreyra', origin: 'C\u00f3rdoba, Argentina / Paris', formed: 1963, active: '1963–present', members: 'Solo composer', description: 'GRM composer whose tape pieces stage small dramas of recorded life — voices, animals, rooms — cut with a dramatist\u2019s timing. Late-career concerts finally gave her work the live-diffusion presence it always implied.', factual: 'Argentine-French composer (b. 1937); worked at GRM from 1963; known for Huellas Entreveradas and Echos.', genreIds: ['musique-concrete', 'field-recording'], labelIds: ['persistence-of-sound', 'ina-grm'] },
  { id: 'delia-derbyshire', name: 'Delia Derbyshire', origin: 'Coventry, England', formed: 1962, active: '1962–1973 (Workshop)', members: 'Composer, with BBC Radiophonic Workshop', description: 'Radiophonic Workshop composer who built electronic music from oscillators, tape loops, and razor-blade edits before voltage control was commonplace. Her Doctor Who theme arrangement showed what careful tape technique could do to a written tune.', factual: 'English electronic musician (1937–2001); realised the Doctor Who theme (1963) at the BBC Radiophonic Workshop.', genreIds: ['musique-concrete', 'experimental-electronic'], labelIds: ['bbc-records'] },
  { id: 'daphne-oram', name: 'Daphne Oram', origin: 'Devizes, England', formed: 1942, active: '1942–2003', members: 'Solo', description: 'Co-founder of the Radiophonic Workshop who left to build the Oramics machine — drawn sound converted photoelectrically into control voltage. Her archive shows a composer thinking about synthesis as drawing, years before the idea became fashionable.', factual: 'English composer (1925–2003); co-founded BBC Radiophonic Workshop (1958); invented the Oramics drawn-sound system.', genreIds: ['musique-concrete', 'experimental-electronic'], labelIds: ['paradigm-discs'] },
  { id: 'eliane-radigue', name: '\u00c9liane Radigue', origin: 'Paris, France', formed: 1968, active: '1968–present', members: 'Solo', description: 'Composer of slow electronic continuity: first with the ARP 2500, later with acoustic instruments played at the edge of audibility. Her pieces ask players to hold partials steady until beating patterns emerge — composition as sustained attention.', factual: 'French composer (b. 1932); known for the ARP-based Trilogie de la Mort (1988–93) and later acoustic works like Occam Ocean.', genreIds: ['drone', 'minimalism', 'spectralism'], labelIds: ['experimental-intermedia'] },
  { id: 'suzanne-ciani', name: 'Suzanne Ciani', origin: 'Indiana, USA', formed: 1974, active: '1974–present', members: 'Solo', description: 'Buchla performer who treats the modular system as a live instrument rather than a programming problem. Early quadraphonic performances used joystick control of spatialisation; the commercial new-age records fund a far stranger live practice.', factual: 'American composer (b. 1946); Buchla specialist; released Seven Waves (1982) on her own label.', genreIds: ['experimental-electronic', 'ambient'], labelIds: ['finders-keepers'] },
  { id: 'alvin-lucier', name: 'Alvin Lucier', origin: 'Nashua, USA', formed: 1965, active: '1965–2021', members: 'Solo composer', description: 'Composer who let rooms, standing waves, and brainwaves do the composing. His scores are short verbal instructions with large acoustic consequences — sit in a room, record, play back, repeat until speech becomes resonance.', factual: 'American composer (1931–2021); taught at Wesleyan; known for I Am Sitting in a Room (1969).', genreIds: ['contemporary', 'minimalism', 'field-recording'], labelIds: ['lovely-music'] },
  { id: 'pauline-oliveros', name: 'Pauline Oliveros', origin: 'Houston, USA', formed: 1961, active: '1961–2016', members: 'Solo / Deep Listening Band', description: 'Accordionist and founder of Deep Listening: improvisation as attention practice. Her tape-delay accordion pieces layer sustained reeds into beating chorales that predate much drone music by decades.', factual: 'American composer and accordionist (1932–2016); founded Deep Listening Institute; known for Accordion & Voice.', genreIds: ['drone', 'free-improv', 'contemporary'], labelIds: ['lovely-music'] },
  { id: 'james-tenney', name: 'James Tenney', origin: 'Silver City, USA', formed: 1961, active: '1961–2006', members: 'Solo composer', description: 'Composer-theorist who moved between computer music, just intonation, and conceptual postal scores. His writing on form and his ensemble pieces share one concern: how listeners group sounds into shapes over time.', factual: 'American composer (1934–2006); wrote Meta-Hodos; known for Postal Pieces and For Ann (Rising).', genreIds: ['contemporary', 'minimalism', 'tape-music'], labelIds: ['new-world'] },
  { id: 'terry-riley', name: 'Terry Riley', origin: 'Colfax, USA', formed: 1960, active: '1960–present', members: 'Solo / ensemble', description: 'Composer of pattern music built from short modules repeated with performer choice. In C outsourced large-scale form to the ensemble\u2019s collective listening — fifty-odd figures, one pulse, no conductor.', factual: 'American composer (b. 1935); composed In C (1964); pioneer of minimalist pattern music.', genreIds: ['minimalism'], labelIds: ['columbia-masterworks'] },
  { id: 'steve-reich', name: 'Steve Reich', origin: 'New York, USA', formed: 1965, active: '1965–present', members: 'Steve Reich and Musicians', description: 'Composer who made process audible: phasing, pulse grids, speech melody. Music for 18 Musicians keeps eleven chords cycling for nearly an hour without ever repeating the same weight twice.', factual: 'American composer (b. 1936); known for Music for 18 Musicians (1976) and Different Trains (1988).', genreIds: ['minimalism', 'contemporary'], labelIds: ['ecm', 'nonesuch'] },
  { id: 'philip-glass', name: 'Philip Glass', origin: 'Baltimore, USA', formed: 1968, active: '1968–present', members: 'Philip Glass Ensemble', description: 'Composer of additive rhythm and arpeggiated harmony for amplified ensemble with Farfisa organ and winds. The early long works build large spans from small numbered changes — arithmetic you can hear.', factual: 'American composer (b. 1937); composed Music in Twelve Parts (1971–74); co-founded Philip Glass Ensemble.', genreIds: ['minimalism', 'contemporary'], labelIds: ['virgin', 'nonesuch'] },
  { id: 'julius-eastman', name: 'Julius Eastman', origin: 'New York, USA', formed: 1968, active: '1968–1990', members: 'Solo / ensemble', description: 'Composer-pianist whose ensemble pieces stack repeated cells until they tip into ecstasy. Femenine layers a vibraphone figure under piano, winds, and percussion for over an hour — minimalism with gospel stamina.', factual: 'American composer (1940–1990); known for Femenine (1974), Evil Nigger, and Gay Guerrilla.', genreIds: ['minimalism', 'contemporary'], labelIds: ['frozen-reeds'] },
  { id: 'gerard-grisey', name: 'G\u00e9rard Grisey', origin: 'Belfort, France', formed: 1972, active: '1972–1998', members: 'Composer', description: 'Founder of spectral music: harmony and form derived from analyses of instrumental spectra. Les Espaces Acoustiques takes one E played across six pieces — from solo viola to full orchestra — and unfolds its partials into architecture.', factual: 'French composer (1946–1998); central figure of spectralism; composed Les Espaces Acoustiques (1974–85).', genreIds: ['spectralism', 'contemporary'], labelIds: ['kairos', 'montaigne'] },
  { id: 'tristan-murail', name: 'Tristan Murail', origin: 'Le Havre, France', formed: 1971, active: '1971–present', members: 'Composer', description: 'Spectral composer who treats the orchestra as a synthesiser: instrumental resynthesis of bell spectra, frequency-shifted harmonies, electronics folded into acoustic writing. Gondwana builds a whole orchestra piece from a single simulated bell.', factual: 'French composer (b. 1947); co-founded L\u2019Itin\u00e9raire; known for Gondwana (1980) and D\u00e9sint\u00e9grations (1983).', genreIds: ['spectralism', 'contemporary'], labelIds: ['mfa', 'kairos'] },
  { id: 'horatiu-radulescu', name: 'Hora\u021biu R\u0103dulescu', origin: 'Bucharest, Romania / Paris', formed: 1969, active: '1969–2008', members: 'Composer', description: 'Composer of bowed-string sound plasmas: many players bowing the same scordatura strings to produce beating bands and difference tones. His music replaces melody with the physics of many bows on few pitches.', factual: 'Romanian-French composer (1942–2008); developed \u201csound plasma\u201d string technique; known for Inner Sound.', genreIds: ['spectralism', 'drone', 'contemporary'], labelIds: ['cybelle'] },
  { id: 'la-monte-young', name: 'La Monte Young', origin: 'Bern, USA', formed: 1958, active: '1958–present', members: 'Theatre of Eternal Music', description: 'Composer of sustained-tone just-intonation environments. The Well-Tuned Piano holds intervals derived from prime-number ratios for hours; the tuning is the piece, and the room completes it.', factual: 'American composer (b. 1935); central to minimalism and Fluxus; known for The Well-Tuned Piano (1964–).', genreIds: ['minimalism', 'drone'], labelIds: ['gramavision'] },
  { id: 'tony-conrad', name: 'Tony Conrad', origin: 'Concord, USA', formed: 1962, active: '1962–2016', members: 'Solo / with Faust', description: 'Violinist and filmmaker who amplified just-intonation drones until the bow noise became part of the harmony. Outside the Dream Syndicate documents his violin against Faust\u2019s motorik — two long-tone systems colliding.', factual: 'American artist and musician (1940–2016); member of Theatre of Eternal Music; made Outside the Dream Syndicate (1973) with Faust.', genreIds: ['minimalism', 'drone', 'krautrock'], labelIds: ['caroline'] },
  { id: 'phill-niblock', name: 'Phill Niblock', origin: 'Anderson, USA', formed: 1968, active: '1968–2024', members: 'Solo composer', description: 'Composer of dense microtonal drones made by layering many slightly detuned instrumental tracks. The result is a thick band of beating frequencies that shifts as you move your head — the listener\u2019s position is part of the instrumentation.', factual: 'American composer (1933–2024); directed Experimental Intermedia; known for Touch-label drone works.', genreIds: ['drone', 'minimalism'], labelIds: ['touch', 'blast-first'] },
  { id: 'morton-feldman', name: 'Morton Feldman', origin: 'New York, USA', formed: 1950, active: '1950–1987', members: 'Composer', description: 'Composer of quiet, long, asymmetrical music where patterns almost repeat. Rothko Chapel holds viola, celesta, percussion, and chorus at low volume for half an hour — dynamics as structure, not decoration.', factual: 'American composer (1926–1987); associated with New York School; composed Rothko Chapel (1971).', genreIds: ['contemporary', 'minimalism'], labelIds: ['odyssey'] },
  { id: 'john-cage', name: 'John Cage', origin: 'Los Angeles, USA', formed: 1938, active: '1938–1992', members: 'Composer', description: 'Composer who reorganised the job description: chance operations, prepared piano, silence as material. The Sonatas and Interludes turn a piano into a percussion ensemble via screws and bolts placed between strings.', factual: 'American composer (1912–1992); known for 4\u203233\u2033 (1952) and Sonatas and Interludes (1946–48).', genreIds: ['contemporary'], labelIds: ['dial', 'mode-records'] },
  { id: 'iannis-xenakis', name: 'Iannis Xenakis', origin: 'Br\u0103ila, Romania / Paris', formed: 1954, active: '1954–2001', members: 'Composer', description: 'Architect-composer who applied stochastic mathematics and game theory to masses of sound. Persepolis layers six channels of horns, strings, and processed material into a polytopal sound field built for a hillside at Persepolis.', factual: 'Greek-French composer (1922–2001); pioneered stochastic music; composed Persepolis (1971).', genreIds: ['contemporary', 'musique-concrete'], labelIds: ['philips'] },
  { id: 'karlheinz-stockhausen', name: 'Karlheinz Stockhausen', origin: 'M\u00f6drath, Germany', formed: 1951, active: '1951–2007', members: 'Composer', description: 'Composer who treated the studio as a compositional parameter: rotation tables, filtered pulse trains, ring modulation. Kontakte organises electronic and instrumental sound on one continuum of pulse rate and pitch.', factual: 'German composer (1928–2007); central to Elektronische Musik at WDR; composed Kontakte (1958–60).', genreIds: ['musique-concrete', 'contemporary'], labelIds: ['wergo'] },
  { id: 'tod-dockstader', name: 'Tod Dockstader', origin: 'Saint Paul, USA', formed: 1958, active: '1958–2015', members: 'Solo', description: 'Self-taught tape composer who built pieces from library sound effects and musique concr\u00e8te technique without institutional support. Quatermass assembles reverberant impacts and drones into something between a film score and a studio etude.', factual: 'American composer (1932–2015); known for Eight Electronic Pieces and Quatermass (1964, Owl).', genreIds: ['musique-concrete', 'tape-music'], labelIds: ['owl'] },
  { id: 'else-marie-pade', name: 'Else Marie Pade', origin: 'Aarhus, Denmark', formed: 1954, active: '1954–2016', members: 'Solo', description: 'Denmark\u2019s first electronic composer, working with tape and oscillators in a home studio from the mid-1950s. Her pieces combine fairy-tale narration with concrete sound — domestic surrealism rendered in spliced tape.', factual: 'Danish composer (1924–2016); pioneer of Danish electronic music; Electronic Works 1958–1995 issued on Dacapo (2002).', genreIds: ['musique-concrete'], labelIds: ['dacapo'] },
  { id: 'amm', name: 'AMM', origin: 'London, England', formed: 1965, active: '1965–present', members: 'Eddie Pr\u00e9vost, Keith Rowe, Lou Gare (orig.)', description: 'Improvising group that treated every sound source — bowed guitar laid flat, transistor radio, snare with chains — as equal. AMMMusic documents a group refusing idiom before \u201cfree improvisation\u201d had a name.', factual: 'British improvising group founded 1965; debut AMMMusic (1967, Elektra). Members have included Keith Rowe and Eddie Pr\u00e9vost.', genreIds: ['free-improv'], labelIds: ['elektra'] },
  { id: 'evan-parker', name: 'Evan Parker', origin: 'Bristol, England', formed: 1969, active: '1969–present', members: 'Solo / many groups', description: 'Saxophonist who developed circular-breathing multiphonics into a continuous polyphonic language. The solo soprano records are feats of breath control and overtone manipulation — one horn sounding like two or three.', factual: 'British saxophonist (b. 1944); known for Saxophone Solos (1976, Incus); co-founded Incus Records.', genreIds: ['free-improv'], labelIds: ['incus'] },
  { id: 'derek-bailey', name: 'Derek Bailey', origin: 'Sheffield, England', formed: 1963, active: '1963–2005', members: 'Solo guitarist', description: 'Guitarist who built a non-idiomatic language from harmonics, scrapes, and Webern-like pointillism. Ballads shows the method applied to standards — tunes fragmented until only their outlines remain.', factual: 'English guitarist (1930–2005); pioneer of free improvisation; founded Incus; known for Ballads and Aida.', genreIds: ['free-improv'], labelIds: ['incus', 'tzadik'] },
  { id: 'cecil-taylor', name: 'Cecil Taylor', origin: 'New York, USA', formed: 1956, active: '1956–2018', members: 'Cecil Taylor Unit', description: 'Pianist whose playing treats the keyboard as eighty-eight tuned drums. Silent Tongues is a solo recital of clustered density, abrupt register shifts, and physical stamina — composition emerging from energy management.', factual: 'American pianist (1929–2018); known for Silent Tongues (1975, Freedom) and Unit Structures (1966, Blue Note).', genreIds: ['free-improv'], labelIds: ['freedom'] },
  { id: 'art-ensemble', name: 'Art Ensemble of Chicago', origin: 'Chicago, USA', formed: 1969, active: '1969–present', members: 'Lester Bowie, Joseph Jarman, Roscoe Mitchell, Malachi Favors, Famoudou Don Moye', description: 'AACM collective combining free playing, theatrical presentation, and pan-African percussion. Their BYG sessions move between fanfares, marches, and collective abstraction without signalling which is the \u201creal\u201d music.', factual: 'American avant-garde jazz group founded 1969; recorded for BYG Actuel including A Jackson in Your House (1969).', genreIds: ['free-improv'], labelIds: ['byg-actuel'] },
  { id: 'sun-ra', name: 'Sun Ra', origin: 'Birmingham, USA', formed: 1955, active: '1955–1993', members: 'Sun Ra Arkestra', description: 'Keyboardist and bandleader whose Arkestra fused swing, free playing, and early synthesisers into a touring cosmology. Space Is the Place pairs big-band voicings with Minimoog smears — eccentricity with strict sectional discipline.', factual: 'American composer and bandleader (1914–1993); led the Arkestra; album Space Is the Place (1973, Blue Thumb).', genreIds: ['free-improv', 'experimental-electronic'], labelIds: ['blue-thumb'] },
  { id: 'ornette-coleman', name: 'Ornette Coleman', origin: 'Fort Worth, USA', formed: 1958, active: '1958–2015', members: 'Quartet / Double Quartet', description: 'Alto saxophonist whose harmolodic theory gave each player equal melodic responsibility. Free Jazz puts two quartets in stereo separation and lets them play simultaneously — collective improvisation as recorded fact, not slogan.', factual: 'American saxophonist (1930–2015); album Free Jazz (1961, Atlantic) gave the movement its name.', genreIds: ['free-improv'], labelIds: ['atlantic'] },
  { id: 'albert-ayler', name: 'Albert Ayler', origin: 'Cleveland, USA', formed: 1962, active: '1962–1970', members: 'Trio / groups', description: 'Tenor saxophonist who played hymns and marches with vibrato wide enough to split the tone. Spiritual Unity strips jazz to tenor, bass, and drums — folk-like themes stated, then overblown into cries.', factual: 'American saxophonist (1936–1970); album Spiritual Unity (1965, ESP-Disk) with Gary Peacock and Sunny Murray.', genreIds: ['free-improv'], labelIds: ['esp-disk'] },
  { id: 'throbbing-gristle', name: 'Throbbing Gristle', origin: 'Hull / London, England', formed: 1975, active: '1975–1981, reunions', members: 'Genesis P-Orridge, Cosey Fanni Tutti, Peter Christopherson, Chris Carter', description: 'Group that named industrial music and built it from cut-ups, cheap synths, and corrosive tape. 20 Jazz Funk Greats pairs pop structures with lyrics and textures designed to curdle them — the catchiest unpleasant record of its era.', factual: 'English group (1975–81); founded Industrial Records; album 20 Jazz Funk Greats (1979).', genreIds: ['industrial', 'experimental-electronic'], labelIds: ['industrial-records'] },
  { id: 'cabaret-voltaire', name: 'Cabaret Voltaire', origin: 'Sheffield, England', formed: 1973, active: '1973–1994, 2009–', members: 'Stephen Mallinder, Richard H. Kirk, Chris Watson (early)', description: 'Sheffield group who ran funk basslines through tape delay and cut-up method. Mix-Up treats the mixing desk as an instrument — versions dubbed, dropped out, and re-entered mid-song.', factual: 'English group formed 1973; album Mix-Up (1979, Rough Trade); early member Chris Watson later of field-recording fame.', genreIds: ['industrial', 'post-punk'], labelIds: ['rough-trade'] },
  { id: 'spk', name: 'SPK', origin: 'Sydney, Australia', formed: 1978, active: '1978–1988', members: 'Graeme Revell, Neil Hill, others', description: 'Australian group who moved from metal-percussion brutality to orchestral electronics. Leichenschrei layers scraped metal, synthetic brass stabs, and treated vocals — industrial music scored like a diseased film orchestra.', factual: 'Australian group (1978–88); album Leichenschrei (1982, Thermidor); Graeme Revell later a film composer.', genreIds: ['industrial', 'power-electronics'], labelIds: ['thermidor'] },
  { id: 'einsturzende', name: 'Einst\u00fcrzende Neubauten', origin: 'Berlin, Germany', formed: 1980, active: '1980–present', members: 'Blixa Bargeld, Alexander Hacke, N.U. Unruh, others', description: 'Berlin group building rhythm from shopping carts, drills, air compressors, and scrap metal. Kollaps records the sound of a city\u2019s infrastructure played as percussion — construction-site music with verse-chorus discipline.', factual: 'German group formed 1980; debut Kollaps (1981, Zick Zack).', genreIds: ['industrial', 'post-punk'], labelIds: ['zick-zack'] },
  { id: 'whitehouse', name: 'Whitehouse', origin: 'London, England', formed: 1980, active: '1980–2008', members: 'William Bennett, Philip Best, others', description: 'Power electronics originators: high-frequency synth scree, pulsing EDP Wasp bass, and shouted text delivered without pause. Bird Seed refined the formula — cleaner production, no less confrontational content.', factual: 'English power electronics group (1980–2008) led by William Bennett; album Bird Seed (2003, Susan Lawly).', genreIds: ['power-electronics', 'noise'], labelIds: ['susan-lawly', 'come-organisation'] },
  { id: 'merzbow', name: 'Merzbow', origin: 'Tokyo, Japan', formed: 1979, active: '1979–present', members: 'Masami Akita', description: 'Project of Masami Akita: hundreds of releases built from pedal chains, tape loops, and later laptop processing. Venereology took harsh noise to a metal label — boosted midrange, relentless stereo movement, no dynamic relief.', factual: 'Japanese noise project of Masami Akita (b. 1956); album Venereology (1994, Relapse).', genreIds: ['noise'], labelIds: ['relapse'] },
  { id: 'masonna', name: 'Masonna', origin: 'Osaka, Japan', formed: 1987, active: '1987–present', members: 'Maso Yamazaki', description: 'Osaka harsh-noise project known for short, violent bursts and chaotic live performance. Shinsen Na Clitoris runs voice and electronics through extreme gain until words become texture.', factual: 'Japanese noise project of Yamazaki \u201cMaso\u201d Takushi (b. 1966); first full-length Shinsen Na Clitoris (1990, Vanilla).', genreIds: ['noise'], labelIds: ['vanilla'] },
  { id: 'hijokaidan', name: 'Hijokaidan', origin: 'Kyoto, Japan', formed: 1979, active: '1979–present', members: 'Jojo Hiroshige, Toshiji Mikawa, others', description: 'Japanese noise collective whose performances mixed destruction, endurance, and amplifier worship. Zouroku captures the early line-up at full pelt — feedback, screamed vocals, and collapsing structures.', factual: 'Japanese noise group formed 1979 led by Jojo Hiroshige; first album Zouroku No Kibyou (April 1982, Unbalance; later Alchemy CD editions).', genreIds: ['noise'], labelIds: ['unbalance'] },
  { id: 'prurient', name: 'Prurient', origin: 'New York, USA', formed: 1998, active: '1998–present', members: 'Dominick Fernow', description: 'Project of Dominick Fernow moving between harsh noise, death industrial, and dark techno. Frozen Niagara Falls is a double album that treats noise as long-form songwriting — synth lines and vocals surfacing from static.', factual: 'American project of Dominick Fernow (b. 1973); album Frozen Niagara Falls (2015, Profound Lore).', genreIds: ['noise', 'power-electronics', 'industrial'], labelIds: ['profound-lore', 'hospital-productions'] },
  { id: 'consumer-electronics', name: 'Consumer Electronics', origin: 'London, England', formed: 1982, active: '1982–present', members: 'Philip Best, others', description: 'Power electronics group built around Philip Best\u2019s shouted narratives over synth and tape-loop backing. Dollhouse Songs pairs domestic horror lyrics with some of the project\u2019s most controlled electronics.', factual: 'English power electronics group led by Philip Best; album Dollhouse Songs (2015, Harbinger Sound).', genreIds: ['power-electronics'], labelIds: ['harbinger-sound'] },
  { id: 'genocide-organ', name: 'Genocide Organ', origin: 'Mannheim, Germany', formed: 1985, active: '1985–present', members: 'Anonymous collective', description: 'Anonymous German death-industrial group: orchestral samples, military percussion, and processed vocals assembled with severe restraint. Leichenlinie set the template — martial rhythms drained of triumph.', factual: 'German death-industrial group formed 1985; debut Leichenlinie (1989, Tesco Organisation).', genreIds: ['power-electronics', 'industrial'], labelIds: ['tesco'] },
  { id: 'ramleh', name: 'Ramleh', origin: 'London, England', formed: 1982, active: '1982–present', members: 'Gary Mundy, Anthony di Franco', description: 'English group spanning power electronics and psychedelic rock. Hole in the Heart documents the early guitar-and-electronics assault — riffs fed through noise until they fray.', factual: 'English group formed 1982 led by Gary Mundy; album Hole in the Heart (1987, Broken Flag).', genreIds: ['power-electronics', 'noise'], labelIds: ['broken-flag'] },
  { id: 'nurse-with-wound', name: 'Nurse With Wound', origin: 'London, England', formed: 1978, active: '1978–present', members: 'Steven Stapleton', description: 'Project of Steven Stapleton: tape collage, surrealist humour, and studio-as-labyrinth. Homotopy to Marie layers drones, chimes, and reversed voices — collage with a comedian\u2019s timing.', factual: 'British project of Steven Stapleton (b. 1957); debut Chance Meeting... (1979); album Homotopy to Marie (1982, United Dairies).', genreIds: ['industrial', 'tape-music'], labelIds: ['united-dairies'] },
  { id: 'coil', name: 'Coil', origin: 'London, England', formed: 1982, active: '1982–2004', members: 'John Balance, Peter Christopherson', description: 'Duo who moved from industrial ritual to elegant electronic song. Horse Rotorvator pairs orchestral samples and drum machines with Balance\u2019s voice — ceremonial music with pop instincts.', factual: 'English duo (1982–2004) of John Balance and Peter Christopherson; album Horse Rotorvator (1986, Force & Form).', genreIds: ['industrial', 'experimental-electronic'], labelIds: ['force-form'] },
  { id: 'current-93', name: 'Current 93', origin: 'London, England', formed: 1982, active: '1982–present', members: 'David Tibet', description: 'Project of David Tibet moving between industrial collage and apocalyptic folk song. Thunder Perfect Mind balances acoustic fingerpicking against unsettling studio treatments.', factual: 'British group led by David Tibet (b. 1960); album Thunder Perfect Mind (1992, Durtro).', genreIds: ['industrial', 'outsider'], labelIds: ['durtro'] },
  { id: 'brian-eno', name: 'Brian Eno', origin: 'Woodbridge, England', formed: 1973, active: '1973–present', members: 'Solo', description: 'Producer and composer who formalised ambient music as a functional category. Discreet Music uses a half-speed tape system to generate slow variations from a few synthesised figures — process music for background attention.', factual: 'English musician (b. 1948); album Discreet Music (1975, Obscure); coined the term ambient music.', genreIds: ['ambient', 'experimental-electronic'], labelIds: ['obscure'] },
  { id: 'aphex-twin', name: 'Aphex Twin', origin: 'Limerick, Ireland / Cornwall', formed: 1991, active: '1991–present', members: 'Richard D. James', description: 'Producer whose ambient works strip techno of drums and keep its sound design. Selected Ambient Works Volume II arranges detuned synth miniatures with long silences — unease rendered in soft tones.', factual: 'Electronic musician Richard D. James (b. 1971); album Selected Ambient Works Volume II (1994, Warp).', genreIds: ['ambient', 'idm'], labelIds: ['warp'] },
  { id: 'autechre', name: 'Autechre', origin: 'Rochdale, England', formed: 1987, active: '1987–present', members: 'Rob Brown, Sean Booth', description: 'Duo whose rhythms moved from hip-hop-derived programming to generative systems. Tri Repetae sits at the hinge: recognisable drums still present, but timbres and tunings already drifting from the grid.', factual: 'English electronic duo (formed 1987); album Tri Repetae (1995, Warp).', genreIds: ['idm'], labelIds: ['warp'] },
  { id: 'boards-of-canada', name: 'Boards of Canada', origin: 'Edinburgh, Scotland', formed: 1986, active: '1986–present', members: 'Marcus Eoin, Mike Sandison', description: 'Duo who process hip-hop tempos and synth melodies through wobble, wow, and faded-tape filtering. Music Has the Right to Children hides dread inside pastoral electronics — detuned leads, degraded drums, subliminal voices.', factual: 'Scottish duo; album Music Has the Right to Children (1998, Warp/Skam).', genreIds: ['idm', 'ambient'], labelIds: ['warp', 'skam'] },
  { id: 'ryoji-ikeda', name: 'Ryoji Ikeda', origin: 'Gifu, Japan', formed: 1995, active: '1995–present', members: 'Solo', description: 'Composer of sine tones, clicks, and data-derived patterns at extreme dynamic range. Dataplex assembles microsecond edits into tracks that test speaker systems and listening stamina alike.', factual: 'Japanese composer (b. 1966); album Dataplex (2005, Raster-Noton); known for audiovisual installations.', genreIds: ['idm', 'minimalism', 'experimental-electronic'], labelIds: ['raster-noton'] },
  { id: 'alva-noto', name: 'Alva Noto', origin: 'Chemnitz, Germany', formed: 1994, active: '1994–present', members: 'Carsten Nicolai', description: 'Project of Carsten Nicolai: clicks, errors, and high-frequency tones arranged with visual-art precision. Vrioon, with Ryuichi Sakamoto\u2019s piano, remains the clearest meeting of glitch process and tonal writing.', factual: 'German artist Carsten Nicolai (b. 1965); album Vrioon (2002, Raster-Noton) with Ryuichi Sakamoto.', genreIds: ['idm', 'minimalism'], labelIds: ['raster-noton'] },
  { id: 'fennesz', name: 'Fennesz', origin: 'Vienna, Austria', formed: 1995, active: '1995–present', members: 'Christian Fennesz', description: 'Guitarist who processes plucked strings through granular and laptop treatments until they behave like weather. Endless Summer keeps the guitar audible — strummed chords dissolving into digital grain.', factual: 'Austrian musician Christian Fennesz (b. 1962); album Endless Summer (2001, Mego).', genreIds: ['idm', 'ambient', 'shoegaze'], labelIds: ['editions-mego'] },
  { id: 'tim-hecker', name: 'Tim Hecker', origin: 'Vancouver, Canada', formed: 2001, active: '2001–present', members: 'Solo', description: 'Composer of distorted organ-and-string masses recorded in churches and then digitally degraded. Ravedeath, 1972 uses a Reykjav\u00edk church organ as source material — sacred tones pushed into speaker-shredding saturation.', factual: 'Canadian musician (b. 1974); album Ravedeath, 1972 (2011, Kranky).', genreIds: ['ambient', 'drone'], labelIds: ['kranky'] },
  { id: 'william-basinski', name: 'William Basinski', origin: 'Houston, USA', formed: 1980, active: '1980–present', members: 'Solo', description: 'Composer who works with decaying tape loops: short melodic fragments that shed oxide — and information — with each pass. The Disintegration Loops documents loops literally falling apart during transfer.', factual: 'American composer (b. 1958); known for The Disintegration Loops (2002–03); works with tape-loop decay.', genreIds: ['ambient', 'tape-music'], labelIds: ['2062'] },
  { id: 'stars-of-the-lid', name: 'Stars of the Lid', origin: 'Austin, USA', formed: 1993, active: '1993–present', members: 'Brian McBride, Adam Wiltzie', description: 'Duo composing for treated guitar, piano, strings, and horns stretched into slow orchestral drifts. Refinement of the Decline is a double album of long arcs — harmony changing at walking pace.', factual: 'American ambient duo; album And Their Refinement of the Decline (2007, Kranky).', genreIds: ['ambient', 'minimalism'], labelIds: ['kranky'] },
  { id: 'lustmord', name: 'Lustmord', origin: 'Denbighshire, Wales', formed: 1980, active: '1980–present', members: 'Brian Williams', description: 'Project of Brian Williams: sub-bass, cavern recordings, and processed ritual sounds. Heresy defined dark ambient — long reverberant decays, crypt acoustics, very little happening very slowly.', factual: 'Project of Brian Williams (b. 1964); album Heresy (1990, Soleimoon); coined the term dark ambient.', genreIds: ['ambient', 'industrial'], labelIds: ['soleimoon'] },
  { id: 'thomas-koner', name: 'Thomas K\u00f6ner', origin: 'Bochum, Germany', formed: 1990, active: '1990–present', members: 'Solo', description: 'Musician and filmmaker whose albums map arctic desolation in low-frequency drones. Permafrost layers gongs and filtered noise into music that seems to lower the room temperature.', factual: 'German musician (b. 1958); album Permafrost (1993, Barooni); known for gong-based drone.', genreIds: ['ambient', 'drone'], labelIds: ['barooni'] },
  { id: 'sunn', name: 'Sunn O)))', origin: 'Seattle, USA', formed: 1998, active: '1998–present', members: 'Stephen O\u2019Malley, Greg Anderson', description: 'Duo playing detuned guitars through walls of Sunn and Model T amplifiers at maximum volume. Monoliths & Dimensions added brass, choir, and orchestration — amplifier worship with arrangement.', factual: 'American drone metal duo formed 1998; album Monoliths & Dimensions (2009, Southern Lord).', genreIds: ['drone'], labelIds: ['southern-lord'] },
  { id: 'earth', name: 'Earth', origin: 'Olympia, USA', formed: 1989, active: '1989–present', members: 'Dylan Carlson', description: 'Group led by Dylan Carlson that slowed metal to tectonic pace. Earth 2 sustains single down-tuned chords for half-hour stretches — riff as drone, distortion as harmony.', factual: 'American group led by Dylan Carlson (b. 1968); album Earth 2: Special Low Frequency Version (1993, Sub Pop).', genreIds: ['drone'], labelIds: ['sub-pop'] },
  { id: 'boris', name: 'Boris', origin: 'Tokyo, Japan', formed: 1992, active: '1992–present', members: 'Takeshi, Wata, Atsuo', description: 'Trio moving between drone, doom, shoegaze, and hardcore without changing personnel. Flood is a single 70-minute piece that moves from fingerpicked patterns to amplifier saturation.', factual: 'Japanese trio formed 1992; album Flood (2000, MIDI Creative).', genreIds: ['drone', 'shoegaze'], labelIds: ['midi-creative'] },
  { id: 'keiji-haino', name: 'Keiji Haino', origin: 'Chiba, Japan', formed: 1970, active: '1970–present', members: 'Solo / Fushitsusha', description: 'Guitarist and vocalist whose playing combines blues inflection, free-jazz density, and amplifier violence. Fushitsusha\u2019s early records document long improvisations that refuse to settle into any one idiom.', factual: 'Japanese musician (b. 1952); leads Fushitsusha; album Allegorical Misunderstanding (1993, Avant) with Yoshida Tatsuya.', genreIds: ['free-improv', 'drone'], labelIds: ['avant'] },
  { id: 'sachiko-m', name: 'Sachiko M', origin: 'Japan', formed: 1994, active: '1994–present', members: 'Solo', description: 'Musician playing sine waves from a sampler with no keyboard — pure tone, memory, and timing. Sine Wave Solo reduces performance to the placement of a few high frequencies in silence.', factual: 'Japanese musician (b. 1973); known for sine-wave sampler works; album Sine Wave Solo (1999, Amethyst).', genreIds: ['lowercase', 'idm'], labelIds: ['amethyst'] },
  { id: 'nakamura', name: 'Toshimaru Nakamura', origin: 'Tokyo, Japan', formed: 1992, active: '1992–present', members: 'Solo', description: 'Musician performing on a mixing desk with no inputs — feedback routed between channels. The no-input board produces high whistles, rumbles, and clicks controlled by fader touch alone.', factual: 'Japanese musician (b. 1965); invented the no-input mixing board; album No-Input Mixing Board (2000, Zero Degree).', genreIds: ['lowercase', 'free-improv'], labelIds: ['zero-degree'] },
  { id: 'steve-roden', name: 'Steve Roden', origin: 'Los Angeles, USA', formed: 1990, active: '1990–2023', members: 'Solo', description: 'Artist who coined \u201clowercase\u201d for music of hushed, small sounds. Forms of Paper amplifies handling noises of paper — faint, close-miked, demanding quiet rooms.', factual: 'American artist (1964–2023); coined \u201clowercase\u201d; album Forms of Paper (2001, Line).', genreIds: ['lowercase', 'field-recording'], labelIds: ['line'] },
  { id: 'bernhard-gunter', name: 'Bernhard G\u00fcnter', origin: 'Neuwied, Germany', formed: 1992, active: '1992–present', members: 'Solo', description: 'Composer of extremely quiet electroacoustic music built from stretched, filtered source sounds. Un Peu de Neige Salie asks listeners to turn the volume up and then rewards them with near-silence.', factual: 'German composer (b. 1957); album Un Peu de Neige Salie (1993, Table of the Elements).', genreIds: ['lowercase', 'musique-concrete'], labelIds: ['table-of-elements'] },
  { id: 'francisco-lopez', name: 'Francisco L\u00f3pez', origin: 'Madrid, Spain', formed: 1982, active: '1982–present', members: 'Solo', description: 'Composer working with field recordings of rainforests and built environments, presented blindfolded and without source credits. La Selva layers Costa Rican recordings into dense rain masses — documentary material heard absolutely.', factual: 'Spanish composer (b. 1964); album La Selva (1998, V2_Archief); performs blindfolded concerts.', genreIds: ['field-recording', 'ambient'], labelIds: ['v2-archief'] },
  { id: 'chris-watson', name: 'Chris Watson', origin: 'Sheffield, England', formed: 1981, active: '1981–present', members: 'Solo', description: 'Former Cabaret Voltaire member turned wildlife recordist. Stepping into the Dark uses extended technique microphones — contact, hydrophone, parabolic — to render animal and weather sound at unfamiliar scale.', factual: 'English recordist (b. 1952); ex-Cabaret Voltaire; album Stepping into the Dark (1996, Touch).', genreIds: ['field-recording'], labelIds: ['touch'] },
  { id: 'jana-winderen', name: 'Jana Winderen', origin: 'Bod\u00f8, Norway', formed: 2005, active: '2005–present', members: 'Solo', description: 'Artist recording underwater environments with hydrophones: cracking ice, fish choruses, boat noise. Energy Field makes aquatic inaudibility present — unfamiliar biophony at high resolution.', factual: 'Norwegian artist (b. 1965); works with hydrophones; album Energy Field (2010, Touch).', genreIds: ['field-recording', 'ambient'], labelIds: ['touch'] },
  { id: 'luc-ferrari', name: 'Luc Ferrari', origin: 'Paris, France', formed: 1958, active: '1958–2005', members: 'Solo composer', description: 'GRM composer who carried a microphone into the world: Presque Rien keeps location recordings nearly unedited, framing everyday sound as composition by attention alone.', factual: 'French composer (1929–2005); composed Presque Rien No. 1 (1970); co-founded GRM-adjacent Groupe de Recherches Musicales work.', genreIds: ['musique-concrete', 'field-recording'], labelIds: ['ina-grm'] },
  { id: 'hildegard-westerkamp', name: 'Hildegard Westerkamp', origin: 'Osnabr\u00fcck, Germany / Vancouver', formed: 1973, active: '1973–present', members: 'Solo', description: 'Composer of soundscape composition: location recordings shaped into narrative forms. Transformations moves between harbour, forest, and studio — place rendered as musical argument.', factual: 'German-Canadian composer (b. 1946); member of World Soundscape Project; album Transformations (1996, Empreintes DIGITALes).', genreIds: ['field-recording', 'musique-concrete'], labelIds: ['empreintes'] },
  { id: 'jandek', name: 'Jandek', origin: 'Houston, USA', formed: 1978, active: '1978–present', members: 'Corwood representative (anonymous)', description: 'Anonymous Corwood Industries project releasing dozens of albums of detuned guitar and idiosyncratic song. Ready for the House pairs atonal fingerpicking with vocals that follow their own pitch logic.', factual: 'Anonymous American project on Corwood Industries; debut Ready for the House (1978, Corwood 0739).', genreIds: ['outsider'], labelIds: ['corwood'] },
  { id: 'the-shaggs', name: 'The Shaggs', origin: 'Fremont, USA', formed: 1968, active: '1968–1975', members: 'Dorothy, Betty, Helen Wiggin', description: 'Sister trio recorded under their father\u2019s direction with rudimentary technique and absolute conviction. Philosophy of the World pairs drifting meters with off-key harmonies — wrongness so consistent it becomes method.', factual: 'American trio of Wiggin sisters; album Philosophy of the World (1969, Third World).', genreIds: ['outsider'], labelIds: ['third-world'] },
  { id: 'r-stevie-moore', name: 'R. Stevie Moore', origin: 'Nashville, USA', formed: 1968, active: '1968–present', members: 'Solo', description: 'Home-recording pioneer with hundreds of self-released albums. Phonography collages pop songs, tape experiments, and studio chatter — DIY as lifelong method, not aesthetic.', factual: 'American musician (b. 1952); known for Phonography (1976, Vital); pioneer of DIY home recording.', genreIds: ['outsider', 'tape-music'], labelIds: ['vital'] },
  { id: 'daniel-johnston', name: 'Daniel Johnston', origin: 'Sacramento, USA', formed: 1980, active: '1980–2019', members: 'Solo', description: 'Songwriter recording hymn-like songs on boombox and cheap organ. Hi, How Are You pairs plainspoken tunes with audible room and tape hiss — fragility as recording fact.', factual: 'American songwriter (1961–2019); album Hi, How Are You (1983, self-released).', genreIds: ['outsider'], labelIds: ['self-released'] },
  { id: 'my-bloody-valentine', name: 'My Bloody Valentine', origin: 'Dublin / London', formed: 1983, active: '1983–present', members: 'Kevin Shields, Bilinda Butcher, Debbie Googe, Colm \u00d3 C\u00edos\u00f3ig', description: 'Group that turned guitar texture into composition: glide-guitar pitch bend, reverse reverb, and whispered vocals buried in mix. Loveless remains the genre\u2019s technical peak — dozens of layered takes per song, no audible edits.', factual: 'Irish-English band formed 1983; album Loveless (1991, Creation).', genreIds: ['shoegaze'], labelIds: ['creation'] },
  { id: 'slowdive', name: 'Slowdive', origin: 'Reading, England', formed: 1989, active: '1989–1995, 2014–', members: 'Rachel Goswell, Neil Halstead, others', description: 'Group pairing dual vocals with volume-swelled guitars and slow tempos. Souvlaki uses Eno and Ginsberg collaborations to widen the blur — songs dissolving at the edges.', factual: 'English band formed 1989; album Souvlaki (1993, Creation).', genreIds: ['shoegaze'], labelIds: ['creation'] },
  { id: 'talk-talk', name: 'Talk Talk', origin: 'London, England', formed: 1981, active: '1981–1991', members: 'Mark Hollis, Lee Harris, Paul Webb', description: 'Band that moved from synth-pop to long-form improvised sessions edited into song shapes. Spirit of Eden records hours of ensemble playing, then carves hymns from the takes.', factual: 'English band (1981–91) led by Mark Hollis; album Spirit of Eden (1988, Parlophone).', genreIds: ['shoegaze', 'free-improv'], labelIds: ['parlophone'] },
  { id: 'slint', name: 'Slint', origin: 'Louisville, USA', formed: 1986, active: '1986–1992, reunions', members: 'Brian McMahan, David Pajo, Britt Walford, Todd Brashear', description: 'Quartet who made quiet-loud dynamics into narrative form: whispered speech, spiderweb guitar harmonics, sudden full-band impacts. Spiderland\u2019s six songs behave like short stories with instrumental climaxes.', factual: 'American band formed 1986; album Spiderland (1991, Touch and Go).', genreIds: ['shoegaze', 'post-punk'], labelIds: ['touch-and-go'] },
  { id: 'tortoise', name: 'Tortoise', origin: 'Chicago, USA', formed: 1990, active: '1990–present', members: 'Dan Bitney, John Herndon, Douglas McCombs, John McEntire, Jeff Parker', description: 'Chicago group fusing krautrock repetition, dub production, and jazz vibraphone. Millions Now Living... builds long tracks from edited jam sessions — the edit deciding the form.', factual: 'American band formed 1990; album Millions Now Living Will Never Die (1996, Thrill Jockey).', genreIds: ['shoegaze', 'krautrock'], labelIds: ['thrill-jockey'] },
  { id: 'godspeed', name: 'Godspeed You! Black Emperor', origin: 'Montreal, Canada', formed: 1994, active: '1994–present', members: 'Large ensemble (anonymous-ish)', description: 'Montreal ensemble writing long crescendo pieces for guitars, strings, and field recordings. Lift Your Skinny Fists pairs drone sections with found-voice monologues — protest music staged as chamber performance.', factual: 'Canadian ensemble formed 1994; album Lift Your Skinny Fists Like Antennas to Heaven (2000, Kranky/Constellation).', genreIds: ['shoegaze'], labelIds: ['kranky', 'constellation'] },
  { id: 'neu', name: 'Neu!', origin: 'D\u00fcsseldorf, Germany', formed: 1971, active: '1971–1975, reunions', members: 'Klaus Dinger, Michael Rother', description: 'Duo who stripped rock to motorik pulse and layered guitar. Neu! 2 — half new material, half manipulated single played at wrong speeds — turned a budget shortfall into a Remix-before-remix statement.', factual: 'German duo (1971–75); album Neu! 2 (1973, Brain).', genreIds: ['krautrock'], labelIds: ['brain'] },
  { id: 'can', name: 'Can', origin: 'Cologne, Germany', formed: 1968, active: '1968–1979, reunions', members: 'Holger Czukay, Irmin Schmidt, Michael Karoli, Jaki Liebezeit, Damo Suzuki / Malcolm Mooney', description: 'Group building long tracks from edited improvisations around Jaki Liebezeit\u2019s disciplined drumming. Tago Mago moves between funk vamps, tape experiments, and vocal derangement across a double album.', factual: 'German band formed 1968; album Tago Mago (1971, United Artists).', genreIds: ['krautrock', 'free-improv'], labelIds: ['united-artists'] },
  { id: 'faust', name: 'Faust', origin: 'W\u00fcmme, Germany', formed: 1971, active: '1971–present', members: 'Werner \u201cZappi\u201d Diermaier, Jean-Herv\u00e9 Peron, others', description: 'Commune-band treating the studio as collage desk: songs interrupted by musique concr\u00e8te inserts. Faust IV tightened the method — actual songs that still get dismantled mid-track.', factual: 'German band formed 1971; album Faust IV (1973, Virgin).', genreIds: ['krautrock', 'tape-music'], labelIds: ['virgin'] },
  { id: 'cluster', name: 'Cluster', origin: 'Berlin, Germany', formed: 1971, active: '1971–2010', members: 'Hans-Joachim Roedelius, Dieter Moebius', description: 'Duo moving from harsh Kluster improvisations to melodic proto-electronics. Zuckerzeit runs drum machines and pastoral synth lines together — kosmische music with pop brevity.', factual: 'German duo (1971–2010); album Zuckerzeit (1974, Brain).', genreIds: ['krautrock', 'experimental-electronic'], labelIds: ['brain'] },
  { id: 'popol-vuh', name: 'Popol Vuh', origin: 'Munich, Germany', formed: 1969, active: '1969–2001', members: 'Florian Fricke, Daniel Fichelscher, others', description: 'Group led by Florian Fricke\u2019s piano and early Moog, fusing sacred music with rock instrumentation. Hosianna Mantra replaces riffs with devotional repetition — quiet music at rock volume levels of commitment.', factual: 'German group (1969–2001) led by Florian Fricke; album Hosianna Mantra (1972, Pilz).', genreIds: ['krautrock', 'ambient'], labelIds: ['pilz'] },
  { id: 'dna', name: 'DNA', origin: 'New York, USA', formed: 1978, active: '1978–1982', members: 'Arto Lindsay, Robin Crutchfield, Ikue Mori', description: 'No wave trio: detuned guitar skronk, organ stabs, and stand-up drumming with no bass. A Taste of DNA compresses songs to ninety seconds — anti-virtuosity played with total precision.', factual: 'American no wave band (1978–82); EP A Taste of DNA (1981, American Clav\u00e9).', genreIds: ['post-punk'], labelIds: ['american-clave'] },
  { id: 'the-pop-group', name: 'The Pop Group', origin: 'Bristol, England', formed: 1977, active: '1977–1981, 2010–', members: 'Mark Stewart, Gareth Sager, others', description: 'Bristol group fusing punk attack, dub production, and free-jazz saxophone. Y, produced by Dennis Bovell, treats the studio as political instrument — rhythm tracks dubbed and deconstructed.', factual: 'English band formed 1977; album Y (1979, Radar).', genreIds: ['post-punk', 'free-improv'], labelIds: ['radar'] },
  { id: 'sonic-youth', name: 'Sonic Youth', origin: 'New York, USA', formed: 1981, active: '1981–2011', members: 'Thurston Moore, Lee Ranaldo, Kim Gordon, Steve Shelley', description: 'Group that brought alternate tunings and prepared-guitar technique to rock song structures. Daydream Nation double album stages long instrumental passages inside pop-length songs.', factual: 'American band (1981–2011); album Daydream Nation (1988, Blast First/Enigma).', genreIds: ['post-punk', 'minimalism'], labelIds: ['blast-first'] },
  { id: 'glenn-branca', name: 'Glenn Branca', origin: 'Harrisburg, USA', formed: 1976, active: '1976–2018', members: 'Ensemble (multiple guitars)', description: 'Composer writing for massed detuned electric guitars. The Ascension stages symphonic structures with rock volume — harmonics and beating patterns doing the work of orchestration.', factual: 'American composer (1948–2018); album The Ascension (1981, 99 Records).', genreIds: ['minimalism', 'post-punk'], labelIds: ['99-records'] },
  { id: 'caterina-barbieri', name: 'Caterina Barbieri', origin: 'Bologna, Italy', formed: 2014, active: '2014–present', members: 'Solo', description: 'Composer building arpeggiated patterns on modular and polyphonic synths. Patterns of Consciousness layers sequenced lines at high tempo until fast repetition fuses into harmony.', factual: 'Italian composer (b. 1990); album Patterns of Consciousness (2017, Important Records).', genreIds: ['experimental-electronic', 'minimalism'], labelIds: ['important'] },
  { id: 'kaitlyn-aurelia-smith', name: 'Kaitlyn Aurelia Smith', origin: 'Orcas Island, USA', formed: 2014, active: '2014–present', members: 'Solo', description: 'Performer composing on Buchla Music Easel with voice layered in close harmony. EARS pairs complex patching with song-like directness — synthesis you can hum.', factual: 'American musician (b. 1987); album EARS (2016, Western Vinyl); Buchla specialist.', genreIds: ['experimental-electronic'], labelIds: ['western-vinyl'] },
  { id: 'sarah-davachi', name: 'Sarah Davachi', origin: 'Calgary, Canada', formed: 2013, active: '2013–present', members: 'Solo', description: 'Composer working with organs, Mellotron, and slow harmonic change. Gave in Rest holds organ tones long enough for room acoustics to become audible counterpoint.', factual: 'Canadian composer (b. 1987); album Gave in Rest (2018, Ba Da Bing).', genreIds: ['drone', 'ambient', 'minimalism'], labelIds: ['ba-da-bing'] },
  { id: 'kali-malone', name: 'Kali Malone', origin: 'Denver, USA / Stockholm', formed: 2017, active: '2017–present', members: 'Solo', description: 'Composer writing for pipe organ and brass in just intonation. The Sacrificial Code stacks slow organ chords so beating patterns emerge — harmony as physical sensation.', factual: 'American-Swedish composer (b. 1994); album The Sacrificial Code (2019, Ideal Recordings).', genreIds: ['drone', 'minimalism', 'contemporary'], labelIds: ['ideal'] },
  { id: 'mica-levi', name: 'Mica Levi', origin: 'London, England', formed: 2013, active: '2013–present', members: 'Solo / with ensemble', description: 'Composer whose film scores treat strings with glissandi, detuning, and close miking. Under the Skin pairs sliding viola lines against throbbing synth — alienation scored for orchestra.', factual: 'English composer (b. 1987); scored Under the Skin (2014, Rough Trade/Milan); Mercury-nominated with Micachu and the Shapes.', genreIds: ['contemporary', 'experimental-electronic'], labelIds: ['rough-trade'] },
  { id: 'arthur-russell', name: 'Arthur Russell', origin: 'Oskaloosa, USA', formed: 1978, active: '1978–1992', members: 'Solo', description: 'Cellist and songwriter moving between disco production and echo-drenched solo cello. World of Echo runs voice and cello through delays and reverb — pop songs heard from inside the effects.', factual: 'American musician (1951–1992); album World of Echo (1986, Upside/Rough Trade).', genreIds: ['contemporary', 'experimental-electronic', 'outsider'], labelIds: ['upside'] },
  { id: 'moondog', name: 'Moondog', origin: 'Marysville, USA', formed: 1949, active: '1949–1999', members: 'Louis Thomas Hardin', description: 'Blind composer who busked on Sixth Avenue in a Viking helmet, writing canons and jazz-inflected miniatures. The 1969 Columbia album arranges his street counterpoint for orchestra.', factual: 'American composer Louis Hardin (1916–1999); album Moondog (1969, Columbia).', genreIds: ['contemporary', 'minimalism', 'outsider'], labelIds: ['columbia'] },
  { id: 'harry-partch', name: 'Harry Partch', origin: 'Oakland, USA', formed: 1930, active: '1930–1974', members: 'Solo / ensemble, self-built instruments', description: 'Composer who built a 43-tone just-intonation instrumentarium because existing instruments couldn\u2019t play his music. Delusion of the Fury stages dance-theatre for adapted guitars, cloud-chamber bowls, and voice.', factual: 'American composer (1901–1974); built custom just-intonation instruments; Delusion of the Fury recorded 1969, issued 1971 (Columbia).', genreIds: ['contemporary', 'minimalism'], labelIds: ['columbia'] },
  { id: 'conlon-nancarrow', name: 'Conlon Nancarrow', origin: 'Texarkana, USA / Mexico City', formed: 1948, active: '1948–1997', members: 'Solo (player piano)', description: 'Composer writing studies for player piano that no human hands could play — simultaneous tempos in irrational ratios punched into rolls. The 1750 Arch recordings document canons at 3:4:5 and faster.', factual: 'American-Mexican composer (1912–1997); known for Studies for Player Piano; recorded for 1750 Arch Records.', genreIds: ['contemporary', 'minimalism'], labelIds: ['1750-arch'] },
  { id: 'the-caretaker', name: 'The Caretaker', origin: 'Manchester, England', formed: 1999, active: '1999–2019', members: 'Leyland Kirby', description: 'Project of Leyland Kirby working with degraded ballroom samples. Everywhere at the End of Time stages dementia as six stages of looping, pitch-dropping fragments — memory loss rendered in mastering moves.', factual: 'Project of Leyland Kirby (b. 1974); six-album series Everywhere at the End of Time (2016–19, History Always Favours the Winners).', genreIds: ['tape-music', 'ambient'], labelIds: ['history-always'] },
  { id: 'negativland', name: 'Negativland', origin: 'Concord, USA', formed: 1979, active: '1979–present', members: 'Mark Hosler, Richard Lyons, others', description: 'Culture-jamming group assembling radio, advertising, and found tape into argumentative collage. Escape from Noise tightened the method into songs — sampling with verse-chorus payoffs.', factual: 'American group formed 1979; album Escape from Noise (1987, SST).', genreIds: ['tape-music', 'industrial'], labelIds: ['sst'] },
  { id: 'john-oswald', name: 'John Oswald', origin: 'Kitchener, Canada', formed: 1969, active: '1969–present', members: 'Solo', description: 'Composer who coined \u201cplunderphonics\u201d for transformative use of existing recordings. Plunderphonics 69/96 stretches and folds pop songs until their hooks become drones.', factual: 'Canadian composer (b. 1953); coined plunderphonics; compilation Plunderphonics 69/96 (2001, Seeland).', genreIds: ['tape-music'], labelIds: ['seeland'] },
  { id: 'swans', name: 'Swans', origin: 'New York, USA', formed: 1982, active: '1982–1997, 2010–present', members: 'Michael Gira, others', description: 'Group led by Michael Gira moving from brutalist repetition to long-form acoustic-electric epics. Filth hammers single chords with two basses; Soundtracks for the Blind sprawls across field recordings and slow builds.', factual: 'American band led by Michael Gira (b. 1954); albums Filth (1983, Neutral) and Soundtracks for the Blind (1996, Young God).', genreIds: ['post-punk', 'industrial', 'drone'], labelIds: ['neutral', 'young-god'] },
  { id: 'scott-walker', name: 'Scott Walker', origin: 'Hamilton, USA / London', formed: 1965, active: '1965–2019', members: 'Solo', description: 'Singer turned avant-garde composer: Tilt pairs orchestral blocks with industrial percussion and lyrics delivered in sealed-room baritone. Pop crooning repurposed as dread delivery system.', factual: 'American-British singer (1943–2019); album Tilt (1995, Fontana).', genreIds: ['contemporary', 'industrial'], labelIds: ['fontana'] },
  { id: 'disco-inferno', name: 'Disco Inferno', origin: 'Essex, England', formed: 1989, active: '1989–1995', members: 'Ian Crause, Paul Wilmott, Rob Whatley', description: 'Trio who replaced guitars with samplers mid-career, triggering found sounds and orchestral stabs from MIDI. D.I. Go Pop documents the method at full stretch — pop songs built from non-musical samples.', factual: 'English band (1989–95); album D.I. Go Pop (1994, Rough Trade).', genreIds: ['post-punk', 'tape-music'], labelIds: ['rough-trade'] },
  { id: 'bark-psychosis', name: 'Bark Psychosis', origin: 'London, England', formed: 1986, active: '1986–present', members: 'Graham Sutton', description: 'Group whose long studio sessions produced hushed, jazz-inflected drift. Hex alternates whisper-quiet passages with sudden ensemble surges — the quietest loud band of its era.', factual: 'English band led by Graham Sutton; album Hex (1994, Circa).', genreIds: ['shoegaze'], labelIds: ['circa'] },
  { id: 'seefeel', name: 'Seefeel', origin: 'London, England', formed: 1992, active: '1992–present', members: 'Mark Clifford, Sarah Peacock, others', description: 'Group processing guitars through samplers and effects until they behave like dub techno. Quique pairs looped guitar figures with sub-bass — shoegaze rhythm section replaced by sound system.', factual: 'English band formed 1992; album Quique (1993, Too Pure).', genreIds: ['shoegaze', 'idm'], labelIds: ['too-pure'] },
  { id: 'oval', name: 'Oval', origin: 'Berlin, Germany', formed: 1991, active: '1991–present', members: 'Markus Popp', description: 'Project that made CD-skipping a compositional method: painting on disc undersides, sampling the stutters. 94 Diskont turns digital errors into pointillist rhythm tracks.', factual: 'Project of Markus Popp (b. 1968); album 94 Diskont (1995, Mille Plateaux).', genreIds: ['idm', 'tape-music'], labelIds: ['mille-plateaux'] },
  { id: 'pole', name: 'Pole', origin: 'Cologne, Germany', formed: 1998, active: '1998–present', members: 'Stefan Betke', description: 'Producer building dub techno from a faulty Waldorf 4-Pole filter that crackles. The numbered albums pair deep bass pulses with that filter\u2019s hiss — malfunction as signature.', factual: 'German producer Stefan Betke (b. 1967); album 1 (1998, Kiff SM/Matador).', genreIds: ['idm', 'experimental-electronic'], labelIds: ['kiff-sm'] },
  { id: 'vladislav-delay', name: 'Vladislav Delay', origin: 'Espoo, Finland', formed: 1997, active: '1997–present', members: 'Sasu Ripatti', description: 'Producer whose Chain Reaction records fused dub delay with glitch edits. Multila moves between fractured beats and submerged chords — techno heard through ice.', factual: 'Finnish producer Sasu Ripatti (b. 1976); album Multila (2000, Chain Reaction).', genreIds: ['idm', 'experimental-electronic'], labelIds: ['chain-reaction'] },
  { id: 'basic-channel', name: 'Basic Channel', origin: 'Berlin, Germany', formed: 1993, active: '1993–present', members: 'Moritz von Oswald, Mark Ernestus', description: 'Duo who reduced techno to chord, delay, and surface noise pressed on heavyweight vinyl. The BCD compilation collects nine singles — dub production as minimalist composition.', factual: 'German duo; compilation BCD (1995, Basic Channel); foundational dub-techno releases.', genreIds: ['experimental-electronic', 'idm'], labelIds: ['basic-channel-label'] },
  { id: 'demdike-stare', name: 'Demdike Stare', origin: 'Manchester, England', formed: 2009, active: '2009–present', members: 'Sean Canty, Miles Whittaker', description: 'Duo assembling occult-tinged electronics from library records, dub, and industrial samples. Symbiosis collects early EPs — foggy loops, low voices, dread without theatrics.', factual: 'English duo; compilation Symbiosis (2009, Modern Love).', genreIds: ['ambient', 'industrial', 'experimental-electronic'], labelIds: ['modern-love'] },
  { id: 'actress', name: 'Actress', origin: 'London, England', formed: 2004, active: '2004–present', members: 'Darren Cunningham', description: 'Producer whose lo-fi techno smears drums and chords into grey-scale smudge. R.I.P. organises that smudge intoside-long arcs — dance music remembered incorrectly.', factual: 'English producer Darren Cunningham (b. 1979); album R.I.P. (2012, Honest Jon\u2019s).', genreIds: ['idm', 'experimental-electronic'], labelIds: ['honest-jons'] },
  { id: 'oneohtrix', name: 'Oneohtrix Point Never', origin: 'Wayland, USA', formed: 2007, active: '2007–present', members: 'Daniel Lopatin', description: 'Project of Daniel Lopatin moving from synth loops to plunderphonic collage. Replica builds tracks from television commercial samples — nostalgia chopped into vapour.', factual: 'American musician Daniel Lopatin (b. 1982); album Replica (2011, Software).', genreIds: ['tape-music', 'experimental-electronic', 'idm'], labelIds: ['software'] },
  { id: 'arca', name: 'Arca', origin: 'Caracas, Venezuela / London', formed: 2012, active: '2012–present', members: 'Alejandra Ghersi', description: 'Producer whose early records pair elastic low-end with unstable song structures. Xen stages voice and synthesiser as mutating bodies — club sounds refusing club form.', factual: 'Venezuelan producer Alejandra Ghersi (b. 1989); album Xen (2014, Mute).', genreIds: ['breakcore-club', 'experimental-electronic'], labelIds: ['mute'] },
  { id: 'elysia-crampton', name: 'Elysia Crampton', origin: 'Riverside, USA', formed: 2015, active: '2015–present', members: 'Solo', description: 'Producer folding reggaet\u00f3n, ambient, and Andean instrumentation into disjunctive epics. American Drift layers flutes and dembow fragments — club history as personal mythology.', factual: 'American producer (b. 1985); album American Drift (2015, Blueberry Records).', genreIds: ['breakcore-club'], labelIds: ['blueberry'] },
  { id: 'jlin', name: 'Jlin', origin: 'Gary, USA', formed: 2015, active: '2015–present', members: 'Jerrilynn Patton', description: 'Footwork producer composing with stripped percussion and sharp negative space. Black Origami arranges drums in asymmetric grids — dance music that counts in unusual numbers.', factual: 'American producer Jerrilynn Patton (b. 1987); album Black Origami (2017, Planet Mu).', genreIds: ['breakcore-club', 'idm'], labelIds: ['planet-mu'] },
  { id: 'sophie', name: 'SOPHIE', origin: 'Glasgow, Scotland', formed: 2013, active: '2013–2021', members: 'Solo', description: 'Producer who synthesised new textures from raw waveforms rather than samples. Oil of Every Pearl\u2019s Un-Insides moves between pop song and material study — sound design as songwriting.', factual: 'Scottish producer (1986–2021); album Oil of Every Pearl\u2019s Un-Insides (2018, Transgressive/MSMSMSM).', genreIds: ['breakcore-club', 'experimental-electronic'], labelIds: ['transgressive'] },
  { id: 'yves-tumor', name: 'Yves Tumor', origin: 'Knoxville, USA', formed: 2015, active: '2015–present', members: 'Sean Bowie', description: 'Project of Sean Bowie moving between noise loops and unstable rock song. Safe in the Hands of Love pairs pop fragments with abrupt edits — songs that distrust their own choruses.', factual: 'Project of Sean Bowie; album Safe in the Hands of Love (2018, Warp).', genreIds: ['breakcore-club', 'post-punk', 'experimental-electronic'], labelIds: ['warp'] },
  { id: 'flying-saucer-attack', name: 'Flying Saucer Attack', origin: 'Bristol, England', formed: 1992, active: '1992–2000, 2015–', members: 'David Pearce', description: 'Project layering distorted guitars and rural psychedelia in lo-fi four-track recordings. Further pairs feedback wash with folk fingerpicking — isolation rendered as production.', factual: 'English project of David Pearce; album Further (1995, Drag City).', genreIds: ['shoegaze', 'outsider'], labelIds: ['drag-city'] },
  { id: 'microstoria', name: 'Microstoria', origin: 'D\u00fcsseldorf, Germany', formed: 1994, active: '1994–2002', members: 'Markus Popp, Jan St. Werner', description: 'Duo of Oval and Mouse on Mars members working in miniature digital edits. Init Ding assembles tiny fragments into playful, pointillist constructions.', factual: 'German duo of Markus Popp and Jan St. Werner; album Init Ding (1995, Thrill Jockey).', genreIds: ['idm'], labelIds: ['thrill-jockey'] },
  { id: 'rhys-chatham', name: 'Rhys Chatham', origin: 'New York, USA', formed: 1977, active: '1977–present', members: 'Ensemble', description: 'Composer-trumpeter writing for massed electric guitars in just intonation. Guitar Trio stages one chord for large ensemble — overtones accumulating until the room rings.', factual: 'American composer (b. 1952); known for Guitar Trio (1977) and Die Donnerg\u00f6tter; recorded for Homestead/Table of the Elements.', genreIds: ['minimalism', 'post-punk'], labelIds: ['homestead'] },
  { id: 'bjork', name: 'Bj\u00f6rk', origin: 'Reykjav\u00edk, Iceland', formed: 1993, active: '1993–present', members: 'Solo', description: 'Singer whose Vespertine paired intimate vocals with Matmos\u2019 microbeats and harp arrangements. Domestic sounds — shuffling cards, cracking ice — programmed as rhythm tracks.', factual: 'Icelandic musician (b. 1965); album Vespertine (2001, One Little Indian) with Matmos programming.', genreIds: ['experimental-electronic', 'contemporary'], labelIds: ['one-little-indian'] },
  { id: 'dean-blunt', name: 'Dean Blunt', origin: 'London, England', formed: 2013, active: '2013–present', members: 'Solo', description: 'Musician whose lo-fi songs stage dub, folk, and R&B fragments with deliberate understatement. Black Metal pairs cracked vocals with sparse guitar — major-label resources used to sound broke.', factual: 'English musician; ex-Hype Williams; album Black Metal (2014, Rough Trade).', genreIds: ['experimental-electronic', 'outsider'], labelIds: ['rough-trade'] },
];
